class Solution:
    def findDuplicates(self, nums: List[int]) -> List[int]:
        res = []
        for n in nums:
            if nums[abs(n)-1] < 0:
                res.append(abs(n))
            else:
                nums[abs(n)-1] *= -1
        return res

reference_solution.javascript:
function findDuplicates(nums) {
    const res = [];
    for (const n of nums) {
        const idx = Math.abs(n) - 1;
        if (nums[idx] < 0) res.push(Math.abs(n));
        else nums[idx] *= -1;
    }
    return res;
}
